import argparse, base64, hashlib, http.client, ipaddress, json, os, re, ssl, sys
from pathlib import Path
from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

ACCOUNT='b03e6ea242724c05eb97eb732cceb21d'
HOST='registry.cloudflare.com'
REPO='bee-validation-20260909-455501a57e820ab6c3eb927b699d02cb'
TAG='ea68e53edb8e'
BASE=f'/v2/{ACCOUNT}/{REPO}'
HERE=Path(__file__).resolve().parent
AAD=f'bee-registry-v1:{ACCOUNT}:{REPO}:{TAG}'.encode()
MEDIA='application/vnd.oci.image.manifest.v1+json'
class Stop(Exception):
    def __init__(self, operation, status=0): self.operation, self.status=operation,status

def digest(data): return 'sha256:'+hashlib.sha256(data).hexdigest()
def b64(s): return base64.b64decode(s,validate=True)
def validate_credentials(c):
    if set(c)!={'account_id','registry_host','username','password'} or c['account_id']!=ACCOUNT or c['registry_host']!=HOST or not all(isinstance(c[k],str) and c[k] and '\r' not in c[k] and '\n' not in c[k] for k in c) or ':' in c['username']:
        raise Stop('credential-shape')
