    if set(envelope)!={'version','iv','wrapped_key','ciphertext'} or envelope['version']!=1: raise Stop('envelope-shape')
    wrapped=key.decrypt(b64(envelope['wrapped_key']),padding.OAEP(mgf=padding.MGF1(hashes.SHA256()),algorithm=hashes.SHA256(),label=None))
    if len(wrapped)!=32 or len(b64(envelope['iv']))!=12: raise Stop('envelope-length')
    return validate_credentials(json.loads(AESGCM(wrapped).decrypt(b64(envelope['iv']),b64(envelope['ciphertext']),AAD)))

def prepare():
    keypath=HERE/'ephemeral-key.pem'
    key=rsa.generate_private_key(public_exponent=65537,key_size=3072)
    pem=key.private_bytes(serialization.Encoding.PEM,serialization.PrivateFormat.PKCS8,serialization.NoEncryption())
    fd=os.open(keypath,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    with os.fdopen(fd,'wb') as f: f.write(pem)
    spki=base64.b64encode(key.public_key().public_bytes(serialization.Encoding.DER,serialization.PublicFormat.SubjectPublicKeyInfo)).decode()
    template=(HERE/'issue-encrypted.js').read_text()
    (HERE/'issue-encrypted-ready.js').write_text(template.replace('__SPKI_BASE64__',spki))
    print(json.dumps({'prepared':True,'public_spki_sha256':hashlib.sha256(b64(spki)).hexdigest()}))

def validate_path(path,upload=False):
    u=urlsplit(path)
    if u.scheme not in ('','https') or u.netloc not in ('',HOST) or u.fragment or '%' in u.path or '\\' in u.path or '..' in u.path or not u.path.startswith(BASE+'/'): raise Stop('registry-location')
    allowed = (re.fullmatch(re.escape(BASE)+r'/blobs/uploads/[A-Za-z0-9_-]+/?',u.path) if upload else (re.fullmatch(re.escape(BASE)+r'/blobs/(sha256:[a-f0-9]{64}|uploads/)',u.path) or re.fullmatch(re.escape(BASE)+r'/manifests/(sha256:[a-f0-9]{64}|'+TAG+r')',u.path)))
    if not allowed: raise Stop('registry-path')
    return urlunsplit(('','',u.path,u.query,''))

def load_image(layout):
    if json.loads((layout/'oci-layout').read_text())!={'imageLayoutVersion':'1.0.0'}: raise Stop('oci-layout')
    idx=json.loads((layout/'index.json').read_text())
    if len(idx['manifests'])!=1: raise Stop('manifest-count')
    def blob(d):
        if not re.fullmatch(r'sha256:[a-f0-9]{64}',d['digest']) or not isinstance(d['size'],int) or d['size']<0 or 'urls' in d: raise Stop('blob-descriptor')
