            data=res.read(limit+1)
            if len(data)>limit: raise Stop('registry-response-size',status)
            return status,selected,data
        finally: conn.close()

def require(status,allowed,operation):
    if status not in allowed: raise Stop(operation,status)

def push(layout,envelopepath):
    keypath=HERE/'ephemeral-key.pem'
    receipt={'image':f'{HOST}/{ACCOUNT}/{REPO}:{TAG}','uploaded_blobs':[],'manifest_published':False,'partial_upload':False}
    try:
        desc,manifest,blobs=load_image(layout)
        credentials=decrypt(json.loads(envelopepath.read_text()),keypath)
        reg=Registry(credentials)
        status,_,_=reg.request('HEAD',BASE+'/manifests/'+TAG)
        require(status,{404},'destination-must-be-absent')
        for d,data in blobs:
            path=BASE+'/blobs/'+d['digest']
            status,h,_=reg.request('HEAD',path)
            require(status,{200,404},'blob-head')
