                receipt['upload_start_outcome']='unknown'
                receipt['partial_upload']=True
                receipt['partial_upload_disposition']='Upload start attempted; outcome unknown until response. No automatic retry.'
                status,h,_=reg.request('POST',BASE+'/blobs/uploads/',body=b'')
                require(status,{202},'upload-start')
                receipt['upload_start_outcome']='accepted'
                receipt['partial_upload']=True
                location=validate_path(h['Location'],True)
                receipt['last_upload_path']=urlsplit(location).path
                receipt['partial_upload_disposition']='Retained only in this nonce repository; no automatic retry or global deletion.'
                u=urlsplit(location); q=parse_qsl(u.query,keep_blank_values=True)
                if any(k=='digest' for k,v in q): raise Stop('unexpected-upload-digest')
                target=urlunsplit(('','',u.path,urlencode(q+[('digest',d['digest'])]),''))
                receipt['blob_commit_outcome']='unknown'
                status,h,_=reg.request('PUT',target,data,'application/octet-stream',upload=True)
                require(status,{201},'blob-commit')
                receipt['blob_commit_outcome']='accepted'
                if h['Docker-Content-Digest']!=d['digest']: raise Stop('blob-write-digest')
                receipt['uploaded_blobs'].append({'digest':d['digest'],'size':d['size']})
                receipt['partial_upload']=False
                receipt['partial_upload_disposition']='Committed and checked by digest.'
                status,h,_=reg.request('HEAD',path)
            require(status,{200},'blob-readback')
            if h['Docker-Content-Digest']!=d['digest'] or h['Content-Length']!=str(d['size']): raise Stop('blob-readback-integrity')
        # Check immutable nonce tag again immediately before final mutation.
        status,_,_=reg.request('HEAD',BASE+'/manifests/'+TAG)
        require(status,{404},'destination-final-absence')
        receipt['manifest_published']=None
        receipt['manifest_put_outcome']='unknown'
        status,h,_=reg.request('PUT',BASE+'/manifests/'+TAG,manifest,MEDIA)
        require(status,{201},'manifest-put')
        receipt['manifest_published']=True
        receipt['manifest_put_outcome']='accepted'
        if h['Docker-Content-Digest']!=desc['digest']: raise Stop('manifest-write-digest')
        for ref in (TAG,desc['digest']):
            status,h,data=reg.request('GET',BASE+'/manifests/'+ref)
            require(status,{200},'manifest-get')
            if data!=manifest or digest(data)!=desc['digest'] or h['Docker-Content-Digest']!=desc['digest']: raise Stop('manifest-readback-integrity')
        for d,_ in blobs:
            status,h,_=reg.request('HEAD',BASE+'/blobs/'+d['digest'])
            require(status,{200},'final-blob-head')
            if h['Docker-Content-Digest']!=d['digest'] or h['Content-Length']!=str(d['size']): raise Stop('final-blob-integrity')
        status,_,_=Registry().request('HEAD',BASE+'/manifests/'+TAG)
        require(status,{401,403},'anonymous-image-must-be-denied')
        receipt['anonymous_access_status']=status
        receipt.update(verified=True,digest=desc['digest'],compressed_bytes=sum(len(v) for _,v in blobs),blob_count=len(blobs))
    except Stop as e: receipt.update(verified=False,operation=e.operation,status=e.status)
    except Exception as e:
        allowed={'gaierror','TimeoutError','SSLError','SSLCertVerificationError','ConnectionError','ConnectionResetError','FileNotFoundError','InvalidTag','ValueError','KeyError','JSONDecodeError','OSError','RemoteDisconnected','IncompleteRead'}
        receipt.update(verified=False,operation='local-or-transport-error',status=0,exception_class=type(e).__name__ if type(e).__name__ in allowed else 'Exception')
        if isinstance(getattr(e,'errno',None),int): receipt['errno']=e.errno
    finally:
        keypath.unlink(missing_ok=True); envelopepath.unlink(missing_ok=True)
        receipt['local_key_and_ciphertext_removed']=not keypath.exists() and not envelopepath.exists()
        (HERE/'push-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
        print(json.dumps(receipt))
    return 0 if receipt.get('verified') else 1

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('operation',choices=['prepare','validate','push']);p.add_argument('--layout',type=Path);p.add_argument('--envelope',type=Path);a=p.parse_args()
